/**
 * Writers for the uncompressed fixtures: WAV and AIFF files generated by
 * code, never real recordings. Options produce the damaged and crafted
 * headers the readers must refuse.
 */

export type WavFormat = "pcm8" | "pcm16" | "pcm24" | "pcm32" | "float32" | "float64";

const BYTES: Record<WavFormat, number> = {
  pcm8: 1,
  pcm16: 2,
  pcm24: 3,
  pcm32: 4,
  float32: 4,
  float64: 8,
};

function ascii(text: string): number[] {
  return [...text].map((char) => char.charCodeAt(0));
}

class Writer {
  readonly bytes: number[] = [];
  text(value: string) {
    this.bytes.push(...ascii(value));
    return this;
  }
  u8(value: number) {
    this.bytes.push(value & 0xff);
    return this;
  }
  u16(value: number, little: boolean) {
    const b = [value & 0xff, (value >> 8) & 0xff];
    this.bytes.push(...(little ? b : b.reverse()));
    return this;
  }
  u32(value: number, little: boolean) {
    const b = [value & 0xff, (value >>> 8) & 0xff, (value >>> 16) & 0xff, (value >>> 24) & 0xff];
    this.bytes.push(...(little ? b : b.reverse()));
    return this;
  }
  raw(values: ArrayLike<number>) {
    for (let i = 0; i < values.length; i += 1) this.bytes.push((values[i] as number) & 0xff);
    return this;
  }
  get length() {
    return this.bytes.length;
  }
}

/** Encodes samples, interleaved, as a WAV or AIFF data chunk stores them. */
function encodeSamples(
  channels: readonly (readonly number[])[],
  bytes: number,
  kind: "int" | "uint" | "float",
  little: boolean,
): Uint8Array<ArrayBuffer> {
  const frames = channels[0]?.length ?? 0;
  const out = new Uint8Array(frames * channels.length * bytes);
  const view = new DataView(out.buffer);
  let offset = 0;
  for (let i = 0; i < frames; i += 1) {
    for (const channel of channels) {
      const sample = Math.max(-1, Math.min(1, channel[i] ?? 0));
      if (kind === "float") {
        if (bytes === 8) view.setFloat64(offset, sample, little);
        else view.setFloat32(offset, sample, little);
      } else if (kind === "uint") {
        view.setUint8(offset, Math.max(0, Math.min(255, Math.round(sample * 128 + 128))));
      } else {
        const scale = 2 ** (bytes * 8 - 1);
        const value = Math.max(-scale, Math.min(scale - 1, Math.round(sample * scale)));
        if (bytes === 1) view.setInt8(offset, value);
        else if (bytes === 2) view.setInt16(offset, value, little);
        else if (bytes === 4) view.setInt32(offset, value, little);
        else {
          const unsigned = value < 0 ? value + 2 ** 24 : value;
          const parts = [unsigned & 0xff, (unsigned >> 8) & 0xff, (unsigned >> 16) & 0xff];
          for (const [index, part] of (little ? parts : parts.reverse()).entries()) {
            view.setUint8(offset + index, part);
          }
        }
      }
      offset += bytes;
    }
  }
  return out;
}

export interface WavOptions {
  readonly sampleRate?: number;
  readonly format?: WavFormat;
  /** WAVE_FORMAT_EXTENSIBLE instead of a plain fmt chunk. */
  readonly extensible?: boolean;
  /** RF64 with a ds64 chunk, and 0xFFFFFFFF in the data chunk's size. */
  readonly rf64?: boolean;
  /** The size written in the data chunk, instead of the real one. */
  readonly dataSize?: number;
  /** A format tag other than PCM or float, such as 0x55 for MP3 in WAV. */
  readonly formatTag?: number;
  /** An odd-sized chunk before fmt, to exercise padding. */
  readonly oddChunk?: boolean;
  /** The data chunk before the fmt chunk. */
  readonly dataFirst?: boolean;
}

/** A WAV file holding these samples, one array per channel. */
export function wavFile(
  channels: readonly (readonly number[])[],
  options: WavOptions = {},
): Uint8Array<ArrayBuffer> {
  const format = options.format ?? "pcm16";
  const bytes = BYTES[format];
  const rate = options.sampleRate ?? 8_000;
  const kind = format.startsWith("float") ? "float" : format === "pcm8" ? "uint" : "int";
  const data = encodeSamples(channels, bytes, kind, true);
  const tag = options.formatTag ?? (kind === "float" ? 3 : 1);

  const fmt = new Writer()
    .text("fmt ")
    .u32(options.extensible ? 40 : 16, true)
    .u16(options.extensible ? 0xfffe : tag, true)
    .u16(channels.length, true)
    .u32(rate, true)
    .u32(rate * channels.length * bytes, true)
    .u16(channels.length * bytes, true)
    .u16(bytes * 8, true);
  if (options.extensible) {
    fmt
      .u16(22, true)
      .u16(bytes * 8, true)
      .u32(0, true)
      .u16(tag, true);
    fmt.raw([0x00, 0x00, 0x00, 0x00, 0x10, 0x00, 0x80, 0x00, 0x00, 0xaa, 0x00, 0x38, 0x9b, 0x71]);
  }
  const dataChunk = new Writer()
    .text("data")
    .u32(options.rf64 ? 0xffffffff : (options.dataSize ?? data.length), true)
    .raw(data);
  if (data.length % 2) dataChunk.u8(0);

  const body = new Writer().text("WAVE");
  if (options.rf64) {
    body.text("ds64").u32(28, true).u32(0, true).u32(0, true);
    body.u32(data.length, true).u32(0, true).u32(0, true).u32(0, true).u32(0, true);
  }
  if (options.oddChunk) body.text("LIST").u32(3, true).raw([1, 2, 3, 0]);
  const chunks = options.dataFirst ? [dataChunk, fmt] : [fmt, dataChunk];
  for (const chunk of chunks) body.raw(chunk.bytes);
  const file = new Writer()
    .text(options.rf64 ? "RF64" : "RIFF")
    .u32(options.rf64 ? 0xffffffff : body.length, true)
    .raw(body.bytes);
  return Uint8Array.from(file.bytes);
}

/** An 80-bit extended-precision number, big-endian, as AIFF stores its rate. */
export function extended(value: number): number[] {
  const exponent = Math.floor(Math.log2(value));
  const mantissa = value / 2 ** exponent; // 1 ≤ mantissa < 2
  const high = Math.floor(mantissa * 2 ** 31);
  const low = Math.floor((mantissa * 2 ** 31 - high) * 2 ** 32);
  const biased = exponent + 16383;
  return [
    (biased >> 8) & 0x7f,
    biased & 0xff,
    (high >>> 24) & 0xff,
    (high >>> 16) & 0xff,
    (high >>> 8) & 0xff,
    high & 0xff,
    (low >>> 24) & 0xff,
    (low >>> 16) & 0xff,
    (low >>> 8) & 0xff,
    low & 0xff,
  ];
}

export type AiffType = "AIFF" | "NONE" | "sowt" | "fl32" | "fl64";

export interface AiffOptions {
  readonly sampleRate?: number;
  /** Bits per sample for integer types. */
  readonly bits?: 8 | 16 | 24 | 32;
  /** Plain AIFF, or AIFC with this compression type. */
  readonly type?: AiffType;
  /** The frame count written in COMM, instead of the real one. */
  readonly frames?: number;
}

/** An AIFF or AIFC file holding these samples, one array per channel. */
export function aiffFile(
  channels: readonly (readonly number[])[],
  options: AiffOptions = {},
): Uint8Array<ArrayBuffer> {
  const type = options.type ?? "AIFF";
  const float = type === "fl32" || type === "fl64";
  const bits = type === "fl64" ? 64 : type === "fl32" ? 32 : (options.bits ?? 16);
  const bytes = bits / 8;
  const data = encodeSamples(channels, bytes, float ? "float" : "int", type === "sowt");
  const frames = channels[0]?.length ?? 0;
  const aifc = type !== "AIFF";

  const comm = new Writer()
    .text("COMM")
    .u32(aifc ? 24 : 18, false)
    .u16(channels.length, false)
    .u32(options.frames ?? frames, false)
    .u16(bits, false)
    .raw(extended(options.sampleRate ?? 8_000));
  if (aifc) comm.text(type).raw([0, 0]); // an empty Pascal string, padded
  const ssnd = new Writer()
    .text("SSND")
    .u32(8 + data.length, false)
    .u32(0, false)
    .u32(0, false)
    .raw(data);
  if (data.length % 2) ssnd.u8(0);
  const body = new Writer()
    .text(aifc ? "AIFC" : "AIFF")
    .raw(comm.bytes)
    .raw(ssnd.bytes);
  return Uint8Array.from(new Writer().text("FORM").u32(body.length, false).raw(body.bytes).bytes);
}
